namespace ghidra.pcodeCPort.slghsymbol;

using ghidra.sleigh.grammar;

public class LabelSymbol : SleighSymbol {

	private int index; // Local 1 up index of label
	private bool isplaced; // Has the label been placed (not just referenced)
	private int refcount; // Number of references to this label

	public LabelSymbol( Location location, string nm, int i ) : base( location, nm )
    {
		index = i;
		refcount = 0;
		isplaced = false;
	}

	public int getIndex() {
		return index;
	}

	public void incrementRefCount() {
		refcount += 1;
	}

	public int getRefCount() {
		return refcount;
	}

	public void setPlaced() {
		isplaced = true;
	}

	public bool isPlaced() {
		return isplaced;
	}

	/* @Override */
    public symbol_type getType() {
		return symbol_type.label_symbol;
	}

}
